import { workflow, node, trigger, sticky, expr, newCredential, ifElse, switchCase, languageModel, memory } from '@n8n/workflow-sdk';

const deployPage = trigger({ type: 'n8n-nodes-base.manualTrigger', version: 1, config: { name: 'Deploy Page', position: [0, 0] }, output: [{}] });
const pageSource = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Page Source', parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "var SOURCE = \"https://raw.githubusercontent.com/mahensaasAI/Trade-Agent/claude/exciting-cray-0j5jt1/ysquare/dist/ysquare.html\";\nreturn [{ json: { url: SOURCE } }];" }, position: [224, 0] }, output: [{ url: "https://raw.githubusercontent.com/mahensaasAI/Trade-Agent/claude/exciting-cray-0j5jt1/ysquare/dist/ysquare.html" }] });
const fetchPage = node({ type: 'n8n-nodes-base.httpRequest', version: 4.4, config: { name: 'Fetch Page', parameters: { method: 'GET', url: expr('{{ $json.url }}'), options: { response: { response: { responseFormat: 'text', outputPropertyName: 'data' } }, timeout: 30000 } }, position: [448, 0] }, output: [{ data: '<!DOCTYPE html>...' }] });
const checkPage = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Check Page', parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "var html = $input.first().json.data;\nif (typeof html !== 'string') html = String(html || '');\nif (html.length < 100 || html.indexOf('<html') < 0) throw new Error('The fetched page does not look like the Y Square app (' + html.length + ' chars). Check the URL in Page Source.');\nreturn [{ json: { page: 'ysquare', bytes: html.length, params: ['ysquare', html, 'Y Square - Deploy UI Page'] } }];" }, position: [672, 0] }, output: [{ page: 'ysquare', bytes: 85000, params: ['ysquare', '<!DOCTYPE html>...', 'Y Square - Deploy UI Page'] }] });
const ensureTable = node({ type: 'n8n-nodes-base.postgres', version: 2.6, config: { name: 'Ensure Table', parameters: { operation: 'executeQuery', query: 'CREATE TABLE IF NOT EXISTS ys_ui_pages (page text PRIMARY KEY, html text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by text)', options: {} }, credentials: { postgres: newCredential('Y Square Postgres') }, alwaysOutputData: true, onError: 'continueRegularOutput', position: [896, 0] }, output: [{}] });
const savePage = node({ type: 'n8n-nodes-base.postgres', version: 2.6, config: { name: 'Save Page', parameters: { operation: 'executeQuery', query: 'INSERT INTO ys_ui_pages (page, html, updated_at, updated_by) VALUES ($1, $2, now(), $3) ON CONFLICT (page) DO UPDATE SET html = EXCLUDED.html, updated_at = now(), updated_by = EXCLUDED.updated_by RETURNING page, length(html) AS bytes, updated_at', options: { queryReplacement: expr("{{ $('Check Page').first().json.params }}") } }, credentials: { postgres: newCredential('Y Square Postgres') }, position: [1120, 0] }, output: [{ page: 'ysquare', bytes: 85000, updated_at: '2026-01-01T00:00:00Z' }] });
const note = sticky("## Y Square - Deploy UI Page\nManual alternative to workflows/deploy_ui.js: fetches the assembled page (ysquare/dist/ysquare.html) from the GitHub repo and upserts it into ys_ui_pages, which the Y Square UI workflow serves at GET /webhook/Y2Workplace.\n\nChange the branch in the Page Source node after merging (main), then run this workflow whenever the page changes.", [pageSource, fetchPage, checkPage], { color: 4 });
export default workflow('ysquare-deploy-ui-page', 'Y Square - Deploy UI Page')
  .add(deployPage).to(pageSource).to(fetchPage).to(checkPage).to(ensureTable).to(savePage);
